const API_URL = 'https://script.google.com/macros/s/AKfycbws0WsrVNNfQFUakWJ7Fa-NFR7urRfTLRVygYXMeEJU1he4rA-KmbNsLZbpePKFe9Q6/exec';
const MONTHS = ['Juli','Agustus','September','Oktober','November','Desember','Januari','Februari','Maret','April','Mei','Juni'];
const MONTH_NUMBER = {Juli:7,Agustus:8,September:9,Oktober:10,November:11,Desember:12,Januari:1,Februari:2,Maret:3,April:4,Mei:5,Juni:6};
const FEE = 10000;
const today = new Date();
const defaultSchoolYear = today.getMonth()+1>=7?today.getFullYear():today.getFullYear()-1;
const currentMonth = MONTHS.find(m=>MONTH_NUMBER[m]===today.getMonth()+1)||'Juli';
const demoMode = !API_URL.startsWith('https://script.google.com/');
const state={siswa:[],pembayaran:[],pemasukan:[],pengeluaran:[],recap:[],activeMonth:currentMonth,schoolYear:defaultSchoolYear,paymentFilter:'all',transactionTab:'income',paymentPeriod:'1',manualMonths:[],reportType:'annual',expenseFilter:'active',isSubmitting:false,lastPaymentCheck:null};
const $=id=>document.getElementById(id);
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
const dateID=v=>{if(!v)return'-';const d=new Date(String(v).slice(0,10)+'T00:00:00');return new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(d)};
const dateInput=()=>`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const yearFor=(month,start=state.schoolYear)=>MONTH_NUMBER[month]>=7?Number(start):Number(start)+1;
const keyFor=(month,start=state.schoolYear)=>`${yearFor(month,start)}-${String(MONTH_NUMBER[month]).padStart(2,'0')}`;
const activeStudents=()=>state.siswa.filter(s=>String(s.STATUS||'AKTIF').toUpperCase()==='AKTIF');
const activeExpenseRows=()=>state.pengeluaran.filter(x=>String(x.STATUS||'AKTIF').toUpperCase()==='AKTIF');
const findPayment=(id,month=state.activeMonth,start=state.schoolYear)=>state.pembayaran.find(p=>String(p.ID_SISWA)===String(id)&&String(p.BULAN).toLowerCase()===month.toLowerCase()&&Number(p.TAHUN)===yearFor(month,start)&&String(p.STATUS||'LUNAS').toUpperCase()==='LUNAS');
const digits=v=>Number(String(v||'').replace(/\D/g,''))||0;
const formatNumberInput=input=>{const value=digits(input.value);input.value=value?new Intl.NumberFormat('id-ID').format(value):''};

function seed(){const names=['Alya Putri','Bima Pratama','Caca Aulia','Daffa Rizky','Elina Zahra','Farel Akbar','Ghina Safira','Hafiz Ilham','Intan Kirana','Jovan Arka','Kayla Anindya','Luthfi Ramadhan'];const siswa=names.map((n,i)=>({ID:`S-${i+1}`,NAMA_SISWA:n,STATUS:'AKTIF'}));const pembayaran=[];MONTHS.forEach((m,mi)=>{if(mi>MONTHS.indexOf(currentMonth))return;siswa.slice(0,Math.max(5,11-mi)).forEach((s,i)=>pembayaran.push({ID:`P-${mi}-${i}`,TANGGAL:`${yearFor(m,defaultSchoolYear)}-${String(MONTH_NUMBER[m]).padStart(2,'0')}-${String(i%18+1).padStart(2,'0')}`,BULAN:m,TAHUN:yearFor(m,defaultSchoolYear),ID_SISWA:s.ID,NAMA_SISWA:s.NAMA_SISWA,NOMINAL:FEE,STATUS:'LUNAS'}))});return{siswa,pembayaran,pemasukan:[{ID:'I-1',TANGGAL:dateInput(),KATEGORI:'Donasi',KETERANGAN:'Donasi wali murid',NOMINAL:150000}],pengeluaran:[{ID:'E-1',TANGGAL:dateInput(),KATEGORI:'Alat tulis',KETERANGAN:'Kertas dan spidol',NOMINAL:75000}]}}
async function api(action,data={},method='GET'){if(demoMode)return demoApi(action,data);const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),25000),started=Date.now();if(location.hostname==='localhost'||location.hostname==='127.0.0.1')console.info(`[API] ${action} dimulai`);try{let response;if(method==='GET'){const url=new URL(API_URL);url.searchParams.set('action',action);Object.entries(data).forEach(([k,v])=>url.searchParams.set(k,v));response=await fetch(url,{signal:controller.signal,cache:'no-store'})}else response=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...data}),signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error(`Server tidak dapat dihubungi (${response.status})`);const result=await response.json();if(!result.success)throw Error(result.message||'Terjadi kesalahan');if(location.hostname==='localhost'||location.hostname==='127.0.0.1')console.info(`[API] ${action} sukses ${Date.now()-started}ms`);return result.data}catch(error){if(error.name==='AbortError'){const timeoutError=new Error('Proses terlalu lama. Periksa data sebelum mencoba kembali.');timeoutError.code='TIMEOUT';throw timeoutError}throw error}finally{clearTimeout(timeout)}}
function demoApi(action,data){const storage='bukuKasB2Mobile';let db=JSON.parse(localStorage.getItem(storage)||'null')||seed();const map={getSiswa:'siswa',getPembayaran:'pembayaran',getPemasukan:'pemasukan',getPengeluaran:'pengeluaran'};if(map[action])return Promise.resolve(db[map[action]]);if(action==='simpanPembayaran'||action==='simpanPembayaranBatch'){const existingRequest=db.pembayaran.filter(p=>data.requestId&&p.REQUEST_ID===data.requestId);if(existingRequest.length)return Promise.resolve({idGrup:existingRequest[0].ID_GRUP,pembayaran:existingRequest,totalPembayaran:existingRequest.reduce((a,x)=>a+Number(x.NOMINAL),0),idempotent:true});const months=action==='simpanPembayaranBatch'?data.bulan:[data.bulan],group=crypto.randomUUID(),saved=[],duplicates=[],created=[];months.forEach(month=>{const year=yearFor(month,Number(data.tahunAjaran??state.schoolYear));if(db.pembayaran.some(p=>p.ID_SISWA===data.idSiswa&&String(p.BULAN).toLowerCase()===month.toLowerCase()&&Number(p.TAHUN)===year)){duplicates.push(month);return}const row={ID:crypto.randomUUID(),ID_GRUP:group,TANGGAL:data.tanggal,BULAN:month,TAHUN:year,ID_SISWA:data.idSiswa,NAMA_SISWA:data.namaSiswa,NOMINAL:data.nominal,STATUS:'LUNAS',KETERANGAN:data.keterangan||'',CREATED_AT:new Date().toISOString(),REQUEST_ID:data.requestId||''};db.pembayaran.push(row);created.push(row);saved.push(month)});if(!saved.length)throw Error('Semua bulan yang dipilih sudah lunas.');localStorage.setItem(storage,JSON.stringify(db));return Promise.resolve({idGrup:group,idSiswa:data.idSiswa,namaSiswa:data.namaSiswa,tanggal:data.tanggal,pembayaran:created,totalPembayaran:created.reduce((a,x)=>a+Number(x.NOMINAL),0),bulanTersimpan:saved,bulanSudahLunas:duplicates})}else if(action==='batalkanPembayaran')db.pembayaran=db.pembayaran.filter(p=>p.ID!==data.id);else if(action==='batalkanPengeluaran'){const item=db.pengeluaran.find(x=>x.ID===data.id);if(!item)throw Error('Pengeluaran tidak ditemukan.');if(item.STATUS==='DIBATALKAN')throw Error('Pengeluaran sudah dibatalkan.');Object.assign(item,{STATUS:'DIBATALKAN',ALASAN_BATAL:data.alasan,DIBATALKAN_PADA:new Date().toISOString(),UPDATED_AT:new Date().toISOString()});localStorage.setItem(storage,JSON.stringify(db));return Promise.resolve({id:item.ID,status:item.STATUS,alasanBatal:item.ALASAN_BATAL,dibatalkanPada:item.DIBATALKAN_PADA})}else{const config={tambahPemasukan:['pemasukan','add'],editPemasukan:['pemasukan','edit'],hapusPemasukan:['pemasukan','delete'],tambahPengeluaran:['pengeluaran','add'],editPengeluaran:['pengeluaran','edit'],hapusPengeluaran:['pengeluaran','delete']}[action];if(config){const[c,op]=config;if(op==='delete')db[c]=db[c].filter(x=>x.ID!==data.id);else{const row={ID:data.id||crypto.randomUUID(),TANGGAL:data.tanggal,KATEGORI:data.kategori,KETERANGAN:data.keterangan,NOMINAL:data.nominal,...(c==='pengeluaran'?{STATUS:'AKTIF',ALASAN_BATAL:'',DIBATALKAN_PADA:'',CREATED_AT:new Date().toISOString(),UPDATED_AT:new Date().toISOString()}:{})};if(op==='edit')db[c][db[c].findIndex(x=>x.ID===data.id)]={...db[c][db[c].findIndex(x=>x.ID===data.id)],...row};else db[c].push(row)}}}localStorage.setItem(storage,JSON.stringify(db));return Promise.resolve({ok:true})}

function toast(message,type='success'){const n=document.createElement('div');n.className=`toast ${type==='error'?'error':''}`;n.textContent=message;$('toastContainer').append(n);setTimeout(()=>n.remove(),3200)}
function showUpdateToast(){if(document.querySelector('.update-toast'))return;const n=document.createElement('div');n.className='toast update-toast';n.innerHTML='<span>Versi baru tersedia</span><button type="button">Muat Ulang</button>';n.querySelector('button').addEventListener('click',()=>location.reload());$('toastContainer').append(n)}
function showLoading(show){$('loadingOverlay').classList.toggle('hidden',!show)}
function switchPage(page){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo({top:0,behavior:'smooth'});if(page==='recap')renderRecap();if(page==='transactions')renderTransactions();if(page==='reports')renderReportMobile()}
function openSheet(id){$('sheetBackdrop').classList.add('open');$(id).classList.add('open');document.body.style.overflow='hidden'}
function closeStudentDropdown(reset=false){$('studentOptionList').classList.add('hidden');$('paymentStudentSearch').setAttribute('aria-expanded','false');if(reset){$('paymentStudentSearch').value='';$('paymentStudentId').value=''}}
function closeSheets(){closeStudentDropdown(true);$('sheetBackdrop').classList.remove('open');document.querySelectorAll('.bottom-sheet').forEach(s=>s.classList.remove('open'));document.body.style.overflow=''}
function confirmAction(title,message){return new Promise(resolve=>{$('confirmTitle').textContent=title;$('confirmMessage').textContent=message;$('confirmOverlay').classList.add('open');const finish=value=>{$('confirmOverlay').classList.remove('open');$('confirmYes').onclick=null;$('confirmNo').onclick=null;resolve(value)};$('confirmYes').onclick=()=>finish(true);$('confirmNo').onclick=()=>finish(false)})}

function updateReportYearOptions(){const found=new Set([defaultSchoolYear-1,defaultSchoolYear,defaultSchoolYear+1]);state.pembayaran.forEach(p=>found.add(MONTH_NUMBER[p.BULAN]>=7?Number(p.TAHUN):Number(p.TAHUN)-1));[...state.pemasukan,...state.pengeluaran].forEach(x=>{const d=new Date(String(x.TANGGAL).slice(0,10)+'T00:00:00');if(!Number.isNaN(d.getTime()))found.add(d.getMonth()+1>=7?d.getFullYear():d.getFullYear()-1)});const current=Number($('reportYear').value||state.schoolYear);$('reportYear').innerHTML=[...found].filter(y=>y>=2020&&y<=2100).sort((a,b)=>a-b).map(y=>`<option value="${y}" ${y===current?'selected':''}>${y}/${y+1}</option>`).join('')}
async function loadAll(overlay=true){if(overlay)showLoading(true);try{const[siswa,pembayaran,pemasukan,pengeluaran]=await Promise.all([api('getSiswa'),api('getPembayaran'),api('getPemasukan'),api('getPengeluaran')]);Object.assign(state,{siswa:siswa||[],pembayaran:pembayaran||[],pemasukan:pemasukan||[],pengeluaran:pengeluaran||[]});updateReportYearOptions();$('connectionDot').classList.add('online');renderAll()}catch(e){toast(e.message,'error')}finally{showLoading(false)}}
function recapData(start=state.schoolYear){const students=activeStudents();return MONTHS.map(month=>{const year=yearFor(month,start),key=keyFor(month,start),payments=state.pembayaran.filter(p=>String(p.BULAN).toLowerCase()===month.toLowerCase()&&Number(p.TAHUN)===year&&String(p.STATUS||'LUNAS').toUpperCase()==='LUNAS'),ids=new Set(payments.map(p=>String(p.ID_SISWA))),paid=students.filter(s=>ids.has(String(s.ID))),unpaid=students.filter(s=>!ids.has(String(s.ID))),cash=payments.reduce((a,p)=>a+Number(p.NOMINAL||0),0),other=state.pemasukan.filter(x=>String(x.TANGGAL).slice(0,7)===key).reduce((a,x)=>a+Number(x.NOMINAL||0),0),expense=activeExpenseRows().filter(x=>String(x.TANGGAL).slice(0,7)===key).reduce((a,x)=>a+Number(x.NOMINAL||0),0);return{month,year,paid,unpaid,cash,other,expense,balance:cash+other-expense}})}

function renderHome(){const recap=recapData(),row=recap.find(r=>r.month===state.activeMonth),total=recap.reduce((a,r)=>a+r.balance,0),count=activeStudents().length,percent=count?Math.round(row.paid.length/count*100):0;$('homeMonthLabel').textContent=`${row.month} ${row.year}`;$('homeBalance').textContent=money(total);$('homeIncome').textContent=money(row.cash+row.other);$('homeExpense').textContent=money(row.expense);$('homePaid').textContent=row.paid.length;$('homeUnpaid').textContent=row.unpaid.length;$('homePercent').textContent=`${percent}%`;$('homeProgress').style.width=`${percent}%`;const tx=[...state.pembayaran.map(x=>({date:x.TANGGAL,title:`Kas ${x.NAMA_SISWA}`,category:`Pembayaran ${x.BULAN}`,amount:x.NOMINAL,type:'income'})),...state.pemasukan.map(x=>({date:x.TANGGAL,title:x.KETERANGAN,category:x.KATEGORI,amount:x.NOMINAL,type:'income'})),...activeExpenseRows().map(x=>({date:x.TANGGAL,title:x.KETERANGAN,category:x.KATEGORI,amount:x.NOMINAL,type:'expense'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,5);$('latestTransactions').innerHTML=tx.length?tx.map(transactionCard).join(''):'<div class="empty">Belum ada transaksi.</div>'}
function transactionCard(x){return`<article class="transaction-card ${x.type}"><span class="icon">${x.type==='expense'?'↑':'↓'}</span><div><b>${escapeHTML(x.title)}</b><small>${escapeHTML(x.category)} · ${dateID(x.date)}</small></div><strong class="amount">${x.type==='expense'?'-':'+'}${money(x.amount)}</strong></article>`}
function renderPayments(){const query=$('studentSearch').value.toLowerCase(),students=activeStudents().filter(s=>String(s.NAMA_SISWA).toLowerCase().includes(query)).filter(s=>{const paid=!!findPayment(s.ID);return state.paymentFilter==='all'||(state.paymentFilter==='paid'&&paid)||(state.paymentFilter==='unpaid'&&!paid)}),all=activeStudents(),paidCount=all.filter(s=>findPayment(s.ID)).length;$('paymentResultCount').textContent=`${students.length} siswa`;$('paymentSummaryText').textContent=`${paidCount} lunas · ${all.length-paidCount} belum`;$('studentCards').innerHTML=students.length?students.map(s=>{const p=findPayment(s.ID),group=p?.ID_GRUP?state.pembayaran.filter(x=>x.ID_GRUP===p.ID_GRUP):[];return`<article class="student-card"><div class="student-card-top"><span class="avatar">${escapeHTML(s.NAMA_SISWA.charAt(0))}</span><div class="student-name"><strong>${escapeHTML(s.NAMA_SISWA)}</strong><small>${p?`Dibayar ${dateID(p.TANGGAL)} · ${money(p.NOMINAL)}`:money(FEE)}</small>${group.length>1?`<span class="group-info">Termasuk pembayaran ${group.length} bulan</span>`:''}</div><span class="status-badge ${p?'paid':''}">${p?'✓ Lunas':'Belum'}</span></div><div class="student-action"><button class="${p?'detail':''}" data-student-id="${escapeHTML(s.ID)}">${p?'Detail':'Bayar'}</button></div></article>`}).join(''):'<div class="empty">Siswa tidak ditemukan.</div>'}
function renderTransactions(){const type=state.transactionTab==='income'?'pemasukan':'pengeluaran';let rows=state[type].filter(x=>!$('transactionMonth').value||String(x.TANGGAL).slice(0,7)===$('transactionMonth').value);if(type==='pengeluaran')rows=rows.filter(x=>state.expenseFilter==='all'||(state.expenseFilter==='active'&&String(x.STATUS||'AKTIF').toUpperCase()==='AKTIF')||(state.expenseFilter==='cancelled'&&String(x.STATUS).toUpperCase()==='DIBATALKAN'));rows.sort((a,b)=>String(b.TANGGAL).localeCompare(String(a.TANGGAL)));const total=rows.filter(x=>type!=='pengeluaran'||String(x.STATUS||'AKTIF').toUpperCase()==='AKTIF').reduce((a,x)=>a+Number(x.NOMINAL||0),0);$('transactionTotalLabel').textContent=`Total ${type}`;$('transactionTotal').textContent=money(total);$('transactionTotal').parentElement.classList.toggle('expense',type==='pengeluaran');$('expenseStatusFilter').classList.toggle('hidden',type!=='pengeluaran');$('transactionCards').innerHTML=rows.length?rows.map(x=>{const cancelled=type==='pengeluaran'&&String(x.STATUS).toUpperCase()==='DIBATALKAN';return`<article class="transaction-card ${type==='pengeluaran'?'expense':''} ${cancelled?'cancelled':''}"><span class="icon">${type==='pengeluaran'?'↑':'↓'}</span><div><b>${escapeHTML(x.KATEGORI)}</b><small>${escapeHTML(x.KETERANGAN)} · ${dateID(x.TANGGAL)}</small><strong class="amount">${money(x.NOMINAL)}</strong>${cancelled?`<span class="cancelled-badge">Dibatalkan</span><small class="cancel-reason">${escapeHTML(x.ALASAN_BATAL||'')} · ${dateID(x.DIBATALKAN_PADA)}</small>`:''}</div>${cancelled?'':`<div class="menu-wrap"><button class="menu-button" data-menu="${x.ID}">⋮</button><div class="menu-popover hidden" id="menu-${x.ID}"><button data-edit="${x.ID}">Edit</button><button data-delete="${x.ID}">${type==='pengeluaran'?'Batalkan Pengeluaran':'Hapus'}</button></div></div>`}</article>`}).join(''):'<div class="empty">Belum ada transaksi pada bulan ini.</div>'}
function renderRecap(){const selectedMonth=$('recapMonth').value||state.activeMonth,start=Number($('recapYear').value||state.schoolYear),recap=recapData(start),row=recap.find(r=>r.month===selectedMonth)||recap[0],total=row.paid.length+row.unpaid.length,percent=total?Math.round(row.paid.length/total*100):0;$('recapCash').textContent=money(row.cash);$('recapOther').textContent=money(row.other);$('recapExpense').textContent=money(row.expense);$('recapBalance').textContent=money(row.balance);$('recapPaid').textContent=row.paid.length;$('recapUnpaid').textContent=row.unpaid.length;$('recapPercent').textContent=`${percent}%`;$('recapProgressBar').style.width=`${percent}%`;$('recapPaymentTitle').textContent=`${row.paid.length} dari ${total} siswa`;$('paidBadge').textContent=row.paid.length;$('unpaidBadge').textContent=row.unpaid.length;$('paidList').innerHTML=row.paid.length?row.paid.map(s=>`<li>${escapeHTML(s.NAMA_SISWA)}</li>`).join(''):'<li>Belum ada</li>';$('unpaidList').innerHTML=row.unpaid.length?row.unpaid.map(s=>`<li>${escapeHTML(s.NAMA_SISWA)}</li>`).join(''):'<li>Tidak ada</li>';$('monthlyRecapCards').innerHTML=recap.map(r=>`<article class="monthly-card"><h3>${r.month} ${r.year}</h3><div class="monthly-stats"><span>Sudah bayar<b>${r.paid.length} siswa</b></span><span>Belum bayar<b>${r.unpaid.length} siswa</b></span><span>Pemasukan<b>${money(r.cash+r.other)}</b></span><span>Pengeluaran<b>${money(r.expense)}</b></span><span>Saldo<b>${money(r.balance)}</b></span></div></article>`).join('')}
function renderAll(){renderHome();renderPayments();renderTransactions();renderRecap();renderReportMobile()}

function selectedPaymentMonths(){return[...document.querySelectorAll('#paymentMonthChecks input:checked')].map(x=>x.value)}
function syncPaymentMonths(){let start=MONTHS.indexOf($('paymentStartMonth').value);const period=state.paymentPeriod;if(period!=='manual'&&start+Number(period)>MONTHS.length){start=MONTHS.length-Number(period);$('paymentStartMonth').value=MONTHS[start];toast(`Bulan mulai disesuaikan agar periode ${period} bulan tetap dalam satu tahun ajaran.`)}const selected=period==='manual'?state.manualMonths:MONTHS.slice(start,start+Number(period));document.querySelectorAll('#paymentMonthChecks input').forEach(input=>{input.checked=selected.includes(input.value);input.disabled=period!=='manual';input.parentElement.classList.toggle('checked',input.checked)});updatePaymentReview()}
function updatePaymentReview(){const months=selectedPaymentMonths(),student=activeStudents().find(s=>String(s.ID)===$('paymentStudentId').value),amount=digits($('paymentAmount').value),duplicates=months.filter(m=>student&&findPayment(student.ID,m));$('paymentMonthCount').textContent=`${months.length} bulan`;$('paymentTotal').textContent=money(months.length*amount);$('reviewName').textContent=student?.NAMA_SISWA||'-';$('reviewDate').textContent=dateID($('paymentDate').value);$('reviewMonths').textContent=months.length?months.map(m=>`${m} ${yearFor(m)}`).join(', '):'-';$('reviewAmount').textContent=money(amount);$('reviewTotal').textContent=money(months.length*amount);$('duplicateNotice').classList.toggle('hidden',!duplicates.length);$('duplicateNotice').textContent=duplicates.length?`Sudah lunas: ${duplicates.join(', ')}. Hanya bulan yang belum lunas akan disimpan.`:''}
function renderStudentOptions(query=''){const current=$('paymentStudentId').value,filtered=activeStudents().filter(s=>s.NAMA_SISWA.toLowerCase().includes(query.toLowerCase()));$('studentOptionList').innerHTML=filtered.length?filtered.map(s=>`<button type="button" class="student-option ${String(s.ID)===current?'selected':''}" role="option" aria-selected="${String(s.ID)===current}" data-student-option="${escapeHTML(s.ID)}"><span>${escapeHTML(s.NAMA_SISWA)}</span>${String(s.ID)===current?'<span class="student-option-check">✓</span>':''}</button>`).join(''):'<div class="student-option-empty">Nama siswa tidak ditemukan</div>'}
function openStudentDropdown(){renderStudentOptions($('paymentStudentSearch').value);$('studentOptionList').classList.remove('hidden');$('paymentStudentSearch').setAttribute('aria-expanded','true');setTimeout(()=>$('paymentStudentSearch').scrollIntoView({block:'center',behavior:'smooth'}),100)}
function chooseStudent(id){const student=activeStudents().find(s=>String(s.ID)===String(id));if(!student)return;$('paymentStudentId').value=student.ID;$('paymentStudentSearch').value=student.NAMA_SISWA;closeStudentDropdown();updatePaymentReview()}
function openPayment(id='',detail=false){closeStudentDropdown(true);if(id)chooseStudent(id);const student=activeStudents().find(s=>String(s.ID)===String($('paymentStudentId').value)),payment=student?findPayment(student.ID):null,group=payment?.ID_GRUP?state.pembayaran.filter(x=>x.ID_GRUP===payment.ID_GRUP):payment?[payment]:[];$('paymentRecordId').value=payment?.ID||'';$('paymentDate').value=payment?String(payment.TANGGAL).slice(0,10):dateInput();$('paymentAmount').value=new Intl.NumberFormat('id-ID').format(payment?.NOMINAL||FEE);$('paymentMethod').value=String(payment?.KETERANGAN||'').startsWith('[Transfer]')?'Transfer':'Tunai';$('paymentNotes').value=String(payment?.KETERANGAN||'').replace(/^\\[(Tunai|Transfer)\\]\\s*/,'');$('paymentStartMonth').value=state.activeMonth;state.paymentPeriod=detail?'manual':'1';state.manualMonths=detail?group.map(x=>x.BULAN):[];document.querySelectorAll('#periodOptions button').forEach(b=>b.classList.toggle('active',b.dataset.period===state.paymentPeriod));$('paymentSheetTitle').textContent=detail?'Detail pembayaran':'Input pembayaran';$('savePayment').classList.toggle('hidden',detail);$('cancelPayment').classList.toggle('hidden',!detail);document.querySelectorAll('#paymentForm input,#paymentForm select,#paymentForm textarea,#periodOptions button').forEach(el=>{if(!el.classList.contains('close-sheet'))el.disabled=detail});syncPaymentMonths();openSheet('paymentSheet')}
