function printReport(){window.print()}
async function shareReport(){const title=`Laporan Kas ${$('reportMonth').value} ${$('reportYear').value}`;if(navigator.share){try{await navigator.share({title,text:`${title}. Gunakan tombol Buat PDF pada preview untuk menyimpan dokumen.`})}catch(e){if(e.name!=='AbortError')toast('Laporan tidak dapat dibagikan.','error')}}else toast('Bagikan tidak didukung browser ini. Gunakan Unduh PDF.','error')}

function bind(){
  document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>switchPage(b.dataset.page));
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>switchPage(b.dataset.go));
  document.querySelectorAll('.close-sheet').forEach(b=>b.onclick=closeSheets);
  $('sheetBackdrop').onclick=closeSheets;
  $('homeMonthButton').onclick=()=>openSheet('monthSheet');
  $('monthGrid').onclick=e=>{const b=e.target.closest('[data-month]');if(!b)return;state.activeMonth=b.dataset.month;$('paymentMonth').value=state.activeMonth;$('recapMonth').value=state.activeMonth;closeSheets();renderAll()};
  document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{const q=b.dataset.quick;if(q==='payment'){switchPage('payments');openPayment()}else{state.transactionTab=q;document.querySelectorAll('#transactionTabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===q));switchPage('transactions');openTransaction(q)}});
  $('openMultiPayment').addEventListener('click',()=>openPayment());
  $('paymentMonth').onchange=e=>{state.activeMonth=e.target.value;$('recapMonth').value=state.activeMonth;renderAll()};
  $('schoolYear').onchange=e=>{state.schoolYear=Number(e.target.value);$('recapYear').value=state.schoolYear;loadAll()};
  $('studentSearch').oninput=renderPayments;
  $('paymentFilters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;state.paymentFilter=b.dataset.filter;document.querySelectorAll('#paymentFilters button').forEach(x=>x.classList.toggle('active',x===b));renderPayments()};
  $('studentCards').addEventListener('click',e=>{const b=e.target.closest('[data-student-id]');if(b)openPayment(b.dataset.studentId,!!findPayment(b.dataset.studentId))});
  $('paymentStudentSearch').addEventListener('focus',openStudentDropdown);
  $('paymentStudentSearch').addEventListener('click',openStudentDropdown);
  $('paymentStudentSearch').addEventListener('input',e=>{renderStudentOptions(e.target.value);$('studentOptionList').classList.remove('hidden');$('paymentStudentSearch').setAttribute('aria-expanded','true');$('paymentStudentId').value='';updatePaymentReview()});
  $('studentOptionList').addEventListener('click',e=>{const option=e.target.closest('[data-student-option]');if(option)chooseStudent(option.dataset.studentOption)});
  document.addEventListener('click',e=>{if(!$('studentCombobox').contains(e.target))closeStudentDropdown()});
  $('paymentDate').onchange=updatePaymentReview;
  $('paymentAmount').oninput=e=>{formatNumberInput(e.target);updatePaymentReview()};
  $('paymentStartMonth').onchange=syncPaymentMonths;
  $('periodOptions').onclick=e=>{const b=e.target.closest('[data-period]');if(!b)return;state.paymentPeriod=b.dataset.period;document.querySelectorAll('#periodOptions button').forEach(x=>x.classList.toggle('active',x===b));syncPaymentMonths()};
  $('paymentMonthChecks').onchange=e=>{if(state.paymentPeriod!=='manual')return;state.manualMonths=selectedPaymentMonths();e.target.parentElement.classList.toggle('checked',e.target.checked);updatePaymentReview()};
  $('transactionAmount').oninput=e=>formatNumberInput(e.target);
  $('paymentForm').onsubmit=async e=>{e.preventDefault();if(state.isSubmitting)return;const student=activeStudents().find(s=>String(s.ID)===$('paymentStudentId').value);if(!student)return toast('Pilih nama siswa.','error');const months=selectedPaymentMonths(),duplicates=months.filter(m=>findPayment(student.ID,m)),fresh=months.filter(m=>!duplicates.includes(m));if(!fresh.length){toast('Pembayaran periode tersebut sudah tercatat.','error');return}if(duplicates.length&&!await confirmAction('Sebagian bulan sudah lunas',`${duplicates.join(', ')} tidak akan disimpan. Lanjutkan bulan lainnya?`))return;const saveButton=$('savePayment'),requestId=crypto.randomUUID(),payload={tanggal:$('paymentDate').value,bulan:months,tahunAjaran:state.schoolYear,idSiswa:student.ID,namaSiswa:student.NAMA_SISWA,nominal:digits($('paymentAmount').value),keterangan:`[${$('paymentMethod').value}] ${$('paymentNotes').value.trim()}`.trim(),requestId};state.isSubmitting=true;state.lastPaymentCheck={studentId:student.ID,months:[...months],schoolYear:state.schoolYear};saveButton.classList.add('button-loading');saveButton.disabled=true;saveButton.textContent='Menyimpan...';$('checkPaymentStatus').classList.add('hidden');try{const result=await api('simpanPembayaranBatch',payload,'POST');if(result.pembayaran?.length)state.pembayaran.push(...result.pembayaran.filter(row=>!state.pembayaran.some(old=>old.ID===row.ID)));closeSheets();renderAll();toast('Pembayaran berhasil disimpan');setTimeout(()=>loadAll(false),0)}catch(error){toast(error.message,'error');if(error.code==='TIMEOUT')$('checkPaymentStatus').classList.remove('hidden')}finally{state.isSubmitting=false;saveButton.classList.remove('button-loading');saveButton.disabled=false;saveButton.textContent='Simpan Pembayaran'}};
  $('checkPaymentStatus').addEventListener('click',async()=>{const check=state.lastPaymentCheck;if(!check)return;showLoading(true);try{const payments=await api('getPembayaran');state.pembayaran=payments||[];renderAll();const found=check.months.some(month=>findPayment(check.studentId,month,check.schoolYear));toast(found?'Pembayaran sudah tersimpan.':'Pembayaran belum ditemukan.');if(found)closeSheets()}catch(error){toast(error.message,'error')}finally{showLoading(false)}});
  $('cancelPayment').onclick=async()=>{if(await confirmAction('Batalkan pembayaran?','Status bulan ini akan kembali menjadi belum bayar.'))mutate('batalkanPembayaran',{id:$('paymentRecordId').value},'Pembayaran berhasil dibatalkan.')};
  $('transactionTabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;state.transactionTab=b.dataset.tab;document.querySelectorAll('#transactionTabs button').forEach(x=>x.classList.toggle('active',x===b));renderTransactions()};
  $('expenseStatusFilter').addEventListener('click',e=>{const b=e.target.closest('[data-expense-filter]');if(!b)return;state.expenseFilter=b.dataset.expenseFilter;document.querySelectorAll('#expenseStatusFilter button').forEach(x=>x.classList.toggle('active',x===b));renderTransactions()});
  $('transactionMonth').onchange=renderTransactions;$('addTransaction').onclick=()=>openTransaction(state.transactionTab);
  $('transactionCards').onclick=async e=>{const menu=e.target.closest('[data-menu]');if(menu){document.querySelectorAll('.menu-popover').forEach(x=>x.classList.add('hidden'));$(`menu-${menu.dataset.menu}`).classList.toggle('hidden');return}const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]'),type=state.transactionTab,noun=type==='income'?'Pemasukan':'Pengeluaran';if(edit)openTransaction(type,edit.dataset.edit);if(del&&type==='expense'){const item=state.pengeluaran.find(x=>String(x.ID)===String(del.dataset.delete));$('cancelExpenseId').value=item.ID;$('cancelExpenseReason').value='';$('cancelExpenseDetail').innerHTML=`<p><strong>${escapeHTML(item.KATEGORI)}</strong></p><p>${dateID(item.TANGGAL)} · ${money(item.NOMINAL)}</p><p>${escapeHTML(item.KETERANGAN)}</p>`;openSheet('cancelExpenseSheet')}else if(del&&await confirmAction(`Hapus ${noun.toLowerCase()}?`,'Data yang dihapus tidak dapat dikembalikan.'))mutate(`hapus${noun}`,{id:del.dataset.delete},`${noun} berhasil dihapus.`)};
  $('cancelExpenseForm').addEventListener('submit',async e=>{e.preventDefault();if(state.isSubmitting)return;const id=$('cancelExpenseId').value,reason=$('cancelExpenseReason').value.trim();if(!reason)return toast('Alasan pembatalan wajib diisi.','error');state.isSubmitting=true;const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;button.classList.add('button-loading');try{const result=await api('batalkanPengeluaran',{id,alasan:reason},'POST'),item=state.pengeluaran.find(x=>String(x.ID)===String(id));if(item)Object.assign(item,{STATUS:'DIBATALKAN',ALASAN_BATAL:result.alasanBatal,DIBATALKAN_PADA:result.dibatalkanPada,UPDATED_AT:result.dibatalkanPada});closeSheets();renderAll();toast('Pengeluaran berhasil dibatalkan');setTimeout(()=>loadAll(false),0)}catch(error){toast(error.message,'error')}finally{state.isSubmitting=false;button.disabled=false;button.classList.remove('button-loading')}});
  $('transactionForm').onsubmit=e=>{e.preventDefault();const type=$('transactionType').value,noun=type==='income'?'Pemasukan':'Pengeluaran',id=$('transactionId').value;mutate(`${id?'edit':'tambah'}${noun}`,{id,tanggal:$('transactionDate').value,kategori:$('transactionCategory').value.trim(),keterangan:$('transactionDescription').value.trim(),nominal:digits($('transactionAmount').value)},`${noun} berhasil ${id?'diperbarui':'ditambahkan'}.`)};
  $('recapMonth').onchange=renderRecap;$('recapYear').onchange=renderRecap;
  $('reportTypeTabs').addEventListener('click',e=>{const b=e.target.closest('[data-report-type]');if(!b)return;state.reportType=b.dataset.reportType;document.querySelectorAll('#reportTypeTabs button').forEach(x=>x.classList.toggle('active',x===b));$('reportMonthField').classList.toggle('hidden',state.reportType==='annual');$('reportFormEyebrow').textContent=state.reportType==='annual'?'Laporan tahun ajaran':'Laporan bulanan';renderReportMobile()});
  $('reportMonth').addEventListener('change',renderReportMobile);$('reportYear').addEventListener('change',renderReportMobile);$('reportForm').onsubmit=e=>{e.preventDefault();buildReport()};$('closePreview').onclick=()=>{$('reportPreview').classList.remove('open');document.body.style.overflow=''};$('printReport').onclick=printReport;$('downloadReport').onclick=printReport;$('shareReport').onclick=shareReport;
}
function init(){const years=[defaultSchoolYear-1,defaultSchoolYear,defaultSchoolYear+1],monthOptions=MONTHS.map(m=>`<option ${m===state.activeMonth?'selected':''}>${m}</option>`).join('');$('paymentMonth').innerHTML=$('recapMonth').innerHTML=$('reportMonth').innerHTML=$('paymentStartMonth').innerHTML=monthOptions;$('schoolYear').innerHTML=years.map(y=>`<option value="${y}" ${y===state.schoolYear?'selected':''}>${y}/${y+1}</option>`).join('');$('recapYear').innerHTML=years.map(y=>`<option value="${y}" ${y===state.schoolYear?'selected':''}>${y}</option>`).join('');$('reportYear').innerHTML=years.map(y=>`<option value="${y}" ${y===state.schoolYear?'selected':''}>${y}/${y+1}</option>`).join('');$('reportMonthField').classList.add('hidden');$('monthGrid').innerHTML=MONTHS.map(m=>`<button data-month="${m}" class="${m===state.activeMonth?'active':''}">${m}</button>`).join('');$('paymentMonthChecks').innerHTML=MONTHS.map(m=>`<label><input type="checkbox" value="${m}">${m}</label>`).join('');$('transactionMonth').value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;bind();loadAll();if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='NEW_VERSION')showUpdateToast()});window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}))}}
document.addEventListener('DOMContentLoaded',init);
